window.CSA_HOWTO={"snake":{"blurb":"Steer your circuit trail with arrows or WASD to eat pellets and grow without crossing your own wires or the wall.","full":["Guide the snake around the grid to eat glowing pellets, which makes your trail grow longer with each one.","Use the arrow keys or WASD to steer; the snake moves continuously in the direction you last pressed.","The run ends the moment you crash into the outer wall or into any part of your own trail, so your score is how many pellets you collected.","Plan turns a few moves ahead, since a long trail leaves less open space to maneuver safely."]},"g2048":{"blurb":"Slide tiles with arrow keys or swipes so matching numbers merge, aiming to build a 2048 tile before the board fills up.","full":["Push all tiles on the board in one direction at a time, trying to combine matching numbers until you reach the 2048 tile.","Use the arrow keys, or swipe on touch devices, to slide every tile as far as it can go in that direction.","When two tiles with the same number collide, they merge into a single tile holding their sum, which adds to your score.","The game ends when the board is full and no adjacent tiles can merge, so try to keep your highest tile tucked in a corner."]},"brick":{"blurb":"Move the paddle with the arrow keys or mouse to bounce the ball and smash every brick without letting it fall.","full":["Break every brick on the screen by bouncing the ball into them, clearing the level once none remain.","Move the paddle left and right using the arrow keys or your mouse to keep the ball in play.","Each brick you hit is destroyed and adds to your score, but losing the ball past the paddle costs a life.","Angle your hits by catching the ball with different parts of the paddle to aim it at tricky, hard-to-reach bricks."]},"flap":{"blurb":"Tap, click, or press space to flap and thread your coin through the gaps without hitting a pipe.","full":["Fly as far as you can by guiding the coin through a never-ending series of pipes without touching any of them.","Press space, click, or tap to flap upward; gravity pulls you back down between flaps.","Passing safely through each gap adds to your score, and the run ends instantly on any collision with a pipe or the ground.","Use short, rhythmic taps instead of long holds to keep your flight smooth and controlled through narrow gaps."]},"memory":{"blurb":"Click or tap cards two at a time to reveal them and clear the board by finding every matching pair.","full":["Clear the board by finding all the matching pairs of cards hidden face down in the grid.","Click or tap one card to flip it, then click or tap a second one to see if they match.","Matching pairs stay face up and count toward clearing the board, while non-matching pairs flip back over so you can try again.","Pay attention to cards you've already seen, since remembering their positions is the key to finding matches faster."]},"glitch":{"blurb":"Click or tap each glitch the instant it pops up on the grid before it vanishes again.","full":["Rack up points by squashing glitches as they randomly pop up across the grid.","Click or tap directly on a glitch as soon as it appears; it will disappear again after a short moment.","Each successful hit scores a point, while glitches you miss simply vanish without penalty.","Keep your eyes moving across the whole grid, since glitches can appear in any spot without warning."]},"stack":{"blurb":"Move and rotate falling blocks with the arrow keys, using down to drop faster, and clear full rows to score.","full":["Stack falling blocks to completely fill horizontal rows, which then clear and add to your score.","Use the arrow keys to move pieces left or right and rotate them, and press down to drop a piece faster.","Any row you fill edge to edge is cleared from the board, and everything above it shifts down.","The game ends when stacked blocks reach the top of the board, so keep the stack low and avoid leaving gaps."]},"pong":{"blurb":"Move your paddle up and down with the arrow keys or W/S to keep the ball in play and win the rally.","full":["Rally the ball back and forth against your opponent, aiming to be first to reach the target score.","Use the Up/Down arrow keys or W and S to move your paddle vertically and intercept the ball.","You score a point whenever the ball gets past your opponent's paddle, and they score when it gets past yours.","Hitting the ball near the edge of your paddle changes its angle, so use that to aim shots away from your opponent."]},"whack":{"blurb":"Click or tap each target the moment it pops up before it disappears to rack up points fast.","full":["Test your reflexes by hitting as many targets as possible before they vanish on their own.","Click or tap a target as soon as it appears on screen; it disappears again after a brief window.","Every target you hit in time adds to your score, while missed or expired targets earn nothing.","Stay focused on the whole play area, since targets can pop up anywhere and speed up as you go."]},"simon":{"blurb":"Watch the growing light and sound sequence, then click or tap the panels back in the same order.","full":["Repeat an ever-growing sequence of lights and sounds correctly to keep the chain going as long as possible.","Watch the panels light up in order first, then click or tap them back in that exact same sequence.","Each round you complete successfully adds one more step to the sequence, raising your score and the challenge.","Making any wrong move in the sequence ends the run, so focus on rhythm and pattern rather than rushing your taps."]},"hoop":{"blurb":"Aim and set your power, then release to sink as many free throws as possible before you run out of attempts.","full":["Score as many baskets as you can from the free-throw line before your attempts or time run out.","Click and drag to aim your shot and set shooting power, then release to shoot.","Each make counts as one point; the game ends when you're out of attempts or time.","A smooth, consistent release matters more than raw power — over- or under-shooting the arc costs makes just as much as bad aim."]},"penalty":{"blurb":"Pick your spot and shoot before the keeper guesses right in this penalty shootout.","full":["Beat the goalkeeper by placing your shot where they aren't diving.","Use click/tap or the arrow keys to aim your shot placement, then shoot.","You score if the keeper dives the wrong way or can't reach your placement; a save or miss ends that attempt.","Aiming for the corners near the posts gives the keeper the least time to react and save."]},"airhockey":{"blurb":"Move your paddle to strike the puck past the AI into their goal; first to the target score wins.","full":["Score more goals than the AI opponent to win the match.","Move your paddle with the mouse/touch or the arrow keys.","Hitting the puck into the opponent's goal scores a point; the match ends when a player reaches the set winning score.","Stay near your own goal line to block incoming shots while looking for openings to counter-attack."]},"tennis":{"blurb":"Move along the baseline and time your swing to return every shot and win the rally.","full":["Outlast your opponent in a rally by returning the ball until they miss.","Move up and down with the arrow keys or mouse, and time your swing as the ball arrives to return it.","Missing a return or hitting it out gives the point to your opponent; win enough points to take the match.","Get into position early and swing right as the ball reaches your side for the cleanest return."]},"boxing":{"blurb":"React on cue with the arrow keys or click zones to land punches and dodge your opponent's swings.","full":["Win the match by landing more punches than you take.","Use the arrow keys or click the on-screen zones to punch or dodge in the cued direction.","Landing a punch on cue scores a hit; failing to dodge in time means you take one instead.","Watch the cue closely — reacting a beat late is the difference between a landed punch and a taken one."]},"golf":{"blurb":"Drag back and release to putt your ball into the hole across the course in as few strokes as possible.","full":["Complete every hole using the fewest total strokes across the course.","Click and drag back, then release to putt — the pullback distance and direction set your power and aim.","Each putt counts as one stroke; your final score is the sum of strokes over all holes, lower is better.","Use walls and slopes to bank your shot toward the hole when a straight line to the cup is blocked."]},"derby":{"blurb":"Time your swing to the incoming pitch and crush balls over the fence for the biggest score.","full":["Rack up the highest total by hitting as many pitches as possible over the fence.","Press space or click, timed to the incoming pitch, to swing.","Solid contact sends the ball for distance, with home runs scoring the biggest points; a mistimed swing whiffs and scores nothing.","Swing a fraction early to catch the pitch out front — that's where you generate the most distance."]},"bowling":{"blurb":"Set your angle and power, then roll to knock down all ten pins in as few rolls as possible.","full":["Knock down all ten pins in each frame across the game.","Click/drag or use the arrow keys to set your angle and power, then release to roll the ball.","You get two rolls per frame; a strike clears all ten pins on the first roll, a spare clears them across both.","Angle your shot slightly off-center rather than straight down the middle to pick up leftover pins for a spare."]},"fieldgoal":{"blurb":"Set your angle and power, then kick to split the uprights before the distance increases each round.","full":["Kick the ball between the uprights to score, advancing through rounds of increasing distance.","Use the arrow keys or drag to set your kick angle and power, then kick.","A kick that splits the uprights scores and sends you to the next, longer attempt; missing wide or short ends your run.","Longer kicks demand more power but leave less room for angle error, so small aiming mistakes hurt more as distance grows."]},"darts":{"blurb":"Aim and set your throw power, then release to hit the bullseye and rack up points across your throws.","full":["Score as many points as possible across your throws by hitting the highest-value areas of the board.","Click and drag to aim and set power, then release to throw the dart.","Points depend on where the dart lands — outer rings are worth less, and the bullseye is worth the most.","Power control matters as much as aim, since even a well-aimed throw can drift wide with too much or too little force."]},"tictactoe":{"blurb":"Place marks in a 3x3 grid and be the first to line up three in a row against the AI.","full":["The goal is to get three of your marks in a row—horizontally, vertically, or diagonally—before the AI does.","Click or tap any empty square on the 3x3 grid to place your mark there.","The game ends the moment either side completes a line of three, or in a draw if the grid fills up first.","Controlling the center square early gives you the most ways to build a winning line."]},"connect4":{"blurb":"Drop discs into columns to connect four of your own in a row before the AI blocks you.","full":["Be the first to line up four of your discs in a row—horizontally, vertically, or diagonally.","Click a column to drop your disc, or use the arrow keys to pick a column and Space to drop it.","Discs stack from the bottom, so the match ends the instant a four-in-a-row appears or the board fills up.","Watch for spots where dropping a disc would set up the AI to win on its very next turn."]},"minesweeper":{"blurb":"Reveal every safe tile and flag the mines without triggering a single explosion.","full":["Clear every tile that doesn't hide a mine while avoiding detonating one.","Click a tile to reveal it, and right-click (or long-press on touch) to flag a tile you suspect hides a mine.","Revealed numbers show how many mines touch that tile—use them to deduce which neighboring tiles are safe; uncovering a mine ends the run.","Start in a corner or open area, and flag suspected mines before clicking nearby to avoid misclicks."]},"codeword":{"blurb":"Decode the number-coded crossword by figuring out which letter each number represents.","full":["Fill in the entire crossword grid by working out which letter each number stands for.","Click a numbered cell, then type a letter to fill it into every cell sharing that number across the grid.","The puzzle is solved once every numbered cell holds a letter that forms valid words in both directions.","Start with short words and frequently repeated numbers—they narrow down letter possibilities fastest."]},"byteRunner":{"blurb":"Dash through an endless run dodging obstacles, then spend earned currency on permanent upgrades.","full":["Run as far as possible without hitting an obstacle, earning currency for distance and pickups along the way.","Press Space or tap to jump and dodge obstacles as they approach.","Each run ends when you hit something; the currency you earned carries over to buy permanent upgrades before your next run.","Prioritize survivability upgrades early—they compound into much longer runs later on."]},"towerAscent":{"blurb":"Climb an endless tower by jumping upward, then upgrade your climber between attempts to reach higher.","full":["Climb as high as possible up an endlessly rising tower before falling or running out of momentum.","Use the arrow keys or WASD, or tap on touch devices, to climb and jump upward between platforms.","Height reached earns currency, which you spend on permanent upgrades to climb even higher on your next attempt.","Time jumps to platform edges rather than rushing—falling ends the run instantly."]},"meteorMiner":{"blurb":"Click meteors to mine resources, then upgrade your drill and cargo to mine faster and haul more.","full":["Mine passing meteors to collect resources before they drift away.","Click or tap a meteor to chip away at it and extract its resources.","Resources mined fill your cargo hold and can be spent on upgrades that increase drill speed and cargo capacity.","Upgrade cargo capacity early so a good mining streak doesn't overflow before you can spend it."]},"zombieSiege":{"blurb":"Shoot down waves of zombies to defend your base, then spend earned currency on upgrades between waves.","full":["Defend your base by eliminating every zombie in each wave before they overrun it.","Click or tap oncoming zombies to shoot them.","Surviving a wave earns currency, which you spend on weapon and defense upgrades before the next, tougher wave begins.","Balance offense and defense upgrades—stronger weapons help, but reinforced defenses buy time when a wave gets overwhelming."]},"byteFarm":{"blurb":"Click to earn data, automate income with generators, and prestige to build lasting power.","full":["Build a data empire by earning currency and growing your income rate over time.","Click to earn currency manually, and spend it on generators that produce currency automatically.","Generators stack to increase your income rate; once progress slows, prestige to reset for a permanent multiplier that speeds up future runs.","Don't be afraid to prestige early—the permanent boost usually pays for itself within minutes of the next run."]},"deepMine":{"blurb":"Click to mine ore, automate the shaft with generators like Drill Rigs and Quantum Rigs, and prestige for lasting power.","full":["Dig for ore and build an automated mining operation that earns currency even when you're not clicking.","Click to earn ore manually, and buy generators—Drill Rig, Server Farm, Data Center, Quantum Rig—to produce it automatically.","Each generator adds to your passive income rate; when growth stalls, prestige to reset progress for a permanent multiplier.","Buy the cheapest available generator upgrade rather than saving for the priciest one—early compounding matters most."]},"cloudLegion":{"blurb":"Click to recruit, automate your army with generators like Tunnel Bore and Orbital Mine, and prestige for lasting power.","full":["Build an army in the clouds by earning currency and automating recruitment.","Click to earn currency manually, and spend it on generators—Tunnel Bore, Refinery, Orbital Mine—that produce currency automatically.","Each generator increases your passive income rate; once growth slows, prestige to reset progress for a permanent power boost.","Reinvest income into generators before spending elsewhere—automated income compounds faster than manual clicking."]},"dungeonDelver":{"blurb":"Fight your way down through the dungeon's monsters, buying gear with gold to survive deeper floors.","full":["Descend floor by floor, defeating monsters that grow tougher—from Rats and Bats to Dragons and Liches—as you go deeper.","Click ATTACK to fight the monster in front of you.","Defeating monsters earns gold, which you spend on gear to hit harder and survive longer against deeper floors.","Gear up between floors rather than pushing ahead underprepared—later monsters hit much harder than early ones."]},"arenaChampion":{"blurb":"Battle your way up the ranked ladder, buying gear with gold to defeat tougher-ranked opponents.","full":["Climb the ranked ladder by defeating opponents one bout at a time, from Rookie up to Grandmaster.","Click ATTACK to fight your current opponent.","Winning a bout earns gold and advances you up the ladder; spend gold on gear to help against tougher-ranked opponents ahead.","Gear up before facing a rank jump—opponents get noticeably stronger as you climb."]},"bossRush":{"blurb":"Fight through a gauntlet of nothing but boss battles, buying gear with gold to survive each one.","full":["Survive a gauntlet made entirely of boss fights, with no regular enemies to warm up on.","Click ATTACK to fight the boss in front of you.","Defeating a boss earns gold, which you spend on gear before facing the next, harder boss in the gauntlet.","Gear up fully between fights—every encounter is a boss fight, so there's no easy round to coast through."]},"orbitRaiders":{"blurb":"Shoot down the descending raider waves before they reach the bottom, moving side to side to dodge return fire.","full":["Destroy every raider in each wave before they descend too far or overwhelm your position.","Use the Arrow keys or A/D to move left and right, and hold Space to fire continuously.","Clear a wave to advance to a faster, tougher one; losing your last life when a raider gets through or hits you ends the run.","Keep moving instead of camping in one spot, since raiders fire back and will pin you down."]},"rockDrift":{"blurb":"Rotate and thrust your ship through the asteroid field, blasting rocks apart before they collide with you.","full":["Survive the asteroid field by destroying every rock before it crashes into your ship.","Left/Right turn your ship, Up applies thrust to drift, and Space fires your weapon.","Large asteroids split into smaller ones when hit, so clearing a field takes multiple shots per rock.","Momentum carries over between thrusts, so ease off before you drift into a rock you meant to avoid."]},"pelletProwler":{"blurb":"Steer through the maze eating every pellet while avoiding whatever's hunting you, before it rebuilds.","full":["Clear every pellet from the maze to complete the level.","Steer with the Arrow keys or WASD, or swipe on mobile to change direction.","Finishing a maze rebuilds it fresh for the next, tougher level.","Plan your route around corners, since your prowler keeps moving in its current direction until you steer into an open path."]},"fleetHunt":{"blurb":"Fire on grid squares to locate and sink all five hidden enemy ships before they sink yours.","full":["Find and sink all five of the opponent's hidden ships before they sink all of yours.","Click a square on the grid to fire, or use the arrow keys to move the cursor and Space to fire.","A hit lets you keep hunting that area for the rest of the ship; sinking every enemy ship wins the game.","Track hits in a line, since ships sit straight, so a hit usually means the surrounding squares are worth checking next."]},"boxLine":{"blurb":"Take turns drawing lines between dots; complete a box's fourth side to claim it and draw again.","full":["Claim more boxes than your rival by completing more squares on the dot grid.","Click near a line to draw it, or use the arrow keys to pick a line and Space to draw it.","Completing a box's fourth side claims it for you and earns an extra turn; otherwise the turn passes to your rival.","Avoid drawing a box's third side when you can, since that hands your rival an easy claim."]},"laneDefense":{"blurb":"Place defenders across five lanes and collect energy to stop the horde before it reaches your house.","full":["Stop every enemy from marching down the five lanes and reaching your house.","Click a defender then a tile to place it, click glowing energy to collect it, or press keys 1-5 to pick a defender.","The run ends if enemies reach your house; surviving each wave lets you field stronger defenses.","Collect energy the moment it appears, since it funds new defenders and an empty lane gets overrun fast."]},"golfCards":{"blurb":"Clear the tableau by playing cards one rank above or below the pile's top card, drawing when stuck.","full":["Clear every card from the table by playing them onto the pile.","Click an open card to play it if it's one rank above or below the pile's top card, or click the pile to turn a new card; arrows plus Space work the same way.","Emptying the table wins the round; running out of moves and draws ends it.","Aces connect to both kings and twos, so save one for when you're stuck between runs."]},"twentyOne":{"blurb":"Bet chips, then hit or stand to beat the dealer's hand without going over twenty-one.","full":["Get closer to 21 than the dealer without busting over it, starting with a 500-chip bankroll.","Use keys 1-4 to set your bet, Space to deal, H to hit, S to stand, D to double down, and C to cash out.","Beating the dealer's hand wins your bet, busting past 21 loses it, and a tie pushes your chips back.","Doubling down locks in one more card for double the bet, so save it for strong starting hands."]},"higherLower":{"blurb":"Guess whether the next card is higher or lower than the current one to build your streak.","full":["Predict each next card correctly to build the longest streak you can.","Press Up or H to guess higher, Down or L to guess lower; ace counts as the lowest card.","A correct guess extends your streak and reveals a new card; three wrong guesses ends the run.","Guesses near the middle of the deck are riskier, so watch which ranks have already come up."]},"hangWord":{"blurb":"Guess letters to reveal the hidden word before six wrong guesses let the fuse reach the bomb.","full":["Uncover the entire hidden word by guessing its letters correctly.","Type a letter on your keyboard or tap it on the on-screen keys.","Correct guesses fill in the word; six wrong guesses burn the fuse down and the bomb goes off.","Start with common vowels and consonants to narrow down the word before the fuse gets short."]},"wordHunt":{"blurb":"Find every hidden word in the letter grid, in any direction, before the timer runs out.","full":["Locate all the hidden words packed into the letter grid before time expires.","Drag from a word's first letter to its last, or press Space to anchor a start point, use arrows to stretch the selection, and Space again to confirm.","Each found word is marked off the list; finding them all before time runs out clears the puzzle.","Words can run in any direction, including diagonally and backward, so scan the grid from multiple angles."]},"laneLeaper":{"blurb":"Hop through traffic and across a river of logs to fill every lily pad on the far bank.","full":["Guide your hopper across the road and river to fill every empty lily pad.","Use the Arrow keys or WASD to hop one step at a time, or swipe on mobile.","Filling all the lily pads clears the level; getting hit by traffic or missing a log in the river costs a life.","Ride the logs instead of jumping past them, since the river offers no safe footing otherwise."]},"swarmStrike":{"blurb":"Shoot down the swarm as it forms up overhead and dive-bombs your position.","full":["Destroy the swarm before its dive-bombing runs overwhelm you.","Use the Arrow keys or A/D to move left and right, and hold Space to fire continuously.","Clearing the whole swarm advances you to the next wave; getting hit by a diving enemy costs a life.","Watch for enemies breaking formation to dive, since they're harder to hit once they're swooping at you."]},"vineCrawler":{"blurb":"Shoot the segmented crawler as it snakes down through your garden, splitting it into smaller pieces.","full":["Destroy the segmented crawler before it reaches the bottom of your garden.","Use the Arrow keys or WASD to move, and hold Space to fire.","Each segment you destroy shortens the crawler, but a hit partway down its body can split it into two smaller crawlers to deal with.","Clearing every remaining segment finishes the wave, so don't ignore the smaller pieces after a split."]},"skyShield":{"blurb":"Aim your cannons and fire to intercept incoming missiles before they wipe out your six cities.","full":["Destroy every missile falling toward your six cities before they hit the ground.","Click or tap where you want to fire, or use the arrow keys to aim and Space to fire.","You lose when all six cities are destroyed; surviving waves scores you points.","Prioritize missiles about to hit a city over ones still high in the sky."]},"softTouchdown":{"blurb":"Rotate and thrust to bring your lander down gently, level, and on the pad before you run out of fuel.","full":["Guide the lander safely onto the landing pad before your fuel runs out.","Use Left/Right to rotate and Up to thrust against gravity.","You succeed only by touching down slow and level on the pad; too fast or tilted ends in a crash.","Tap short thruster bursts rather than holding Up, so you don't burn through fuel or overshoot."]},"neonTrails":{"blurb":"Steer your light trail to box in the rival racer before they box in you.","full":["Trap your rival by forcing them to crash into a trail, wall, or their own path first.","Use the arrow keys or WASD to turn (there are no brakes), or swipe on mobile.","Crashing into any trail or wall ends the game; the last rider left moving wins.","Cut off open space early, since you can't slow down or reverse once you're boxed in."]},"silverBall":{"blurb":"Flip the paddles to keep the ball in play and rack up the highest score before your last ball drains.","full":["Keep the ball bouncing around the table and hit targets to build your score.","Use Left/Right arrows (or Z/M) to flip the paddles, and Space to nudge the table.","The game ends when you drain your last ball; your final score is what you racked up along the way.","Nudge sparingly. Too much shaking can tilt the table and lock your flippers."]},"caveCopter":{"blurb":"Hold to climb and let go to sink as you fly your copter through the twisting cave without touching the walls.","full":["Fly as far as possible through the winding cave without crashing into a wall.","Hold Space, Up, or click to climb; release to sink back down.","Touching a cave wall ends the run; your distance traveled is your score.","Tap in short bursts instead of holding down, so you can thread narrow gaps precisely."]},"skyHopper":{"blurb":"Bounce upward from platform to platform, steering left and right, and see how high you can climb without falling.","full":["Climb as high as possible by bouncing from platform to platform.","Use Left/Right or A/D to steer in midair, or drag on mobile.","Falling off the bottom of the screen ends the run; your height reached is your score.","Line yourself up before you land on a platform, since you can't steer while standing still."]},"pyramidHop":{"blurb":"Hop diagonally across the pyramid to change every cube's color while dodging the chasers on your tail.","full":["Repaint every cube on the pyramid by landing on it, while avoiding the chasing enemies.","Use the arrows to hop diagonally (Up = up-right, Left = up-left, Down = down-left, Right = down-right), or Q/E/Z/C, or tap a corner.","Getting caught by a chaser costs you a life; clear the whole pyramid to complete the level.","Plan a route that loops back on itself, since every hop is diagonal and you can't move straight."]},"dirtDigger":{"blurb":"Dig through the dirt, pump up critters until they burst, or drop rocks on them to clear each level.","full":["Clear each level by defeating every critter tunneling through the dirt below.","Use the arrows or WASD to dig your own tunnels, and tap Space to pump up the critter in front of you.","Pump a critter until it inflates and pops for points, or lure it under a rock and drop the rock for an instant kill.","Watch your flanks. Critters can burrow through solid dirt faster than you can dig through it."]},"craterCruiser":{"blurb":"Drive across the crater field, jumping pits and shooting boulders and saucers before they take you down.","full":["Survive the crater field by jumping obstacles and destroying everything that shoots at you.","Press Space or Up to jump craters, and X or Z to fire forward and upward.","Getting hit by a boulder, bomb, or saucer costs a life; surviving further and destroying enemies raises your score.","Fire upward before a saucer passes overhead, since its bombs drop straight down on you."]},"botSwarm":{"blurb":"Move with one hand and shoot with the other to blast the robot swarm and rescue stranded humans.","full":["Survive the robot swarm while rescuing as many stranded humans as you can.","Move with WASD or the arrow keys, and shoot with I/J/K/L, or click and hold.","Touching an enemy costs a life; each human you rescue adds to your score.","Move and shoot in different directions at once to clear a path while covering your back."]},"landGrab":{"blurb":"Move along the edge and draw lines to fence off territory, sealing off 75% of the field while dodging the wild spark.","full":["Claim territory by drawing lines that seal off sections of the field.","Use the arrows or WASD to move and draw; fence off 75% of the area to clear the level.","Touching the wild spark while you're drawing a line costs you a life, so finish each line quickly.","Draw short lines back to already-claimed ground rather than risking a long line across open space."]},"fruitSlash":{"blurb":"Drag or swipe across the fruit to slice it, but keep your finger off the bombs.","full":["Slice as much fruit as you can while avoiding the bombs.","Drag or swipe across the screen to cut through any fruit that crosses your path.","Slicing a bomb ends the game instantly; letting 3 pieces of fruit fall unsliced also ends it.","Chain multiple fruits in one swipe for combo points instead of slicing them one at a time."]},"towerStack":{"blurb":"Tap at the right moment to drop each sliding block squarely onto the tower and stack it as high as possible.","full":["Stack blocks as high as you can by dropping each one perfectly onto the block below.","Tap, click, or press Space to drop the sliding block.","Any overhang gets sliced off; if you miss the tower entirely, the tower ends there.","Wait for the block to be dead-center over the tower rather than dropping the instant it appears."]},"helixFall":{"blurb":"Rotate the tower so the falling ball drops through the gaps in each ring, avoiding every red platform.","full":["Guide the falling ball down through the tower by rotating it so a gap lines up under the ball.","Use Left/Right or drag to rotate the tower.","Landing on a red platform ends the run; passing through open gaps keeps the ball falling and your score climbing.","Rotate early. It's easier to line up a gap before the ball is about to land than at the last instant."]},"hueHopper":{"blurb":"Tap to hop through the spinning rings, but only leap through the segment that matches your color.","full":["Hop as far as you can through a tower of spinning color-coded rings.","Tap, click, or press Space to hop upward.","Hopping into a ring segment that doesn't match your color ends the run; matching colors keeps you climbing.","Watch the ring's spin ahead of time so your color's gap is lined up before you jump."]},"beatTiles":{"blurb":"Tap the dark tile in every row, in order, before it scrolls past, as the pace keeps speeding up.","full":["Tap the dark tile in each row as it scrolls down, without missing one or hitting a wrong lane.","Use D, F, J, K (or the arrow keys) for the four lanes, or tap the tile directly.","Missing the dark tile or tapping the wrong lane ends the run; the game speeds up the longer you survive.","Keep your fingers resting over all four lanes so you're never reaching for the right key."]},"perfectTen":{"blurb":"Start and stop a hidden clock by feel, trying to land exactly on the target time.","full":["Stop the clock as close as possible to the hidden target time, using timing alone.","Press Space or click to start the clock, then press again to stop it.","The clock face is hidden while it runs, so you're judging elapsed time purely by feel.","Count a steady rhythm in your head instead of guessing, since you get no visual feedback until you stop."]},"coinCatcher":{"blurb":"Steer your basket left and right to catch coins and gems, dodge the bombs, and keep your combo alive.","full":["Catch as many coins and gems as you can to build score and combo, while dodging bombs.","Use Left/Right, or move the mouse, or drag to steer the basket.","Catching a bomb breaks your combo or costs a life; catching items back to back raises your combo multiplier.","Stay near the center of the screen so you can react to drops on either side."]},"typeRush":{"blurb":"Type each falling word correctly before it reaches the ground to clear it and rack up your score.","full":["Clear falling words by typing them out completely before they hit the ground.","This is a keyboard-only game: type the letters of the falling word you're targeting to clear it.","Press Backspace to unlock a different target word if you want to switch which one you're typing.","Letting a word reach the bottom costs you, so prioritize the word closest to the ground."]},"targetBlitz":{"blurb":"Click each target as fast as you can before it shrinks away, and aim for the center for a bigger score.","full":["Click or tap targets before they shrink out of existence, scoring more for hits closer to the center.","Click or tap each target as soon as it appears; 3 misses ends the game.","A shrinking target is worth less the longer you wait, so react fast rather than lining up a perfect center shot.","Missing a target counts against your 3-miss limit just like clicking empty space, so only go for ones you're confident about."]},"jewelJam":{"blurb":"Swap two neighbouring gems to line up three or more of the same colour before you run out of moves.","full":["Match three or more gems of the same colour in a row or column to clear them and score points.","Click two neighbouring gems to swap them, or drag one gem onto another; arrows plus Space also work.","You have 25 moves total, and every swap counts even if it doesn't make a match, so plan ahead.","Bigger matches and chains score more, and clearing gems can trigger cascades as new gems fall into place."]},"slideSort":{"blurb":"Slide tiles into the empty space to put the numbers back in order using as few moves as possible.","full":["Arrange the numbered tiles in ascending order, left to right, top to bottom, with the empty space last.","Click any tile that lines up with the gap to slide it in, or use the arrow keys; choose a 3x3 or 4x4 board first.","Only a tile directly in line with the empty space can move, so you may need several slides to reposition one number.","Your score rewards solving in fewer moves, so plan a sequence rather than sliding tiles at random."]},"switchGrid":{"blurb":"Press tiles to flip them and their neighbours until every light on the board is switched off.","full":["The goal is to turn every tile off; pressing one tile toggles it and the tiles directly above, below, left and right of it.","Click a tile to press it, or move with the arrows and press Space; R restarts the board but costs you a life.","Because each press affects a cross of five tiles, solving usually means working section by section rather than chasing single lights.","Watch your lives: careless restarts add up, so try to think through the pattern before resetting."]},"diskTower":{"blurb":"Move the entire disk stack to the right-hand peg one disk at a time without ever placing a big disk on a smaller one.","full":["Rebuild the full tower on the far-right peg, moving only one disk at a time.","Click a peg to lift its top disk, then click another peg to drop it there; keys 1, 2, 3 or arrows plus Space do the same.","A larger disk can never rest on a smaller one, and you only have a limited number of moves to finish.","The classic technique moves the smallest disk every other turn, cycling between the same two pegs, to shift the stack efficiently."]},"cratePush":{"blurb":"Push every crate onto a glowing pad without pulling any crate back, using as few moves as you can.","full":["Clear the level by pushing every crate onto a glowing target pad; the level ends once all pads are covered.","Move with the arrow keys or WASD (swipe on touch); walking into a crate pushes it one space in that direction.","You can only push crates, never pull them, so a crate shoved into a corner or against two walls can get permanently stuck.","Use Z to undo a bad push or R to restart the level, and think a few moves ahead before committing to a push."]},"codeBreaker":{"blurb":"Guess the hidden four-colour code, using black and white pin feedback to crack it in as few rows as possible.","full":["A secret sequence of four colours is hidden; guess it correctly to win before you run out of rows.","Click colours to fill a row and press OK, or use keys 1-6 to place colours, Backspace to remove one, and Enter to submit.","After each guess, a black pin means one peg is the right colour in the right slot, and a white pin means right colour, wrong slot.","Use the count of black and white pins together across guesses to narrow down both the colours and their order."]},"pixelCross":{"blurb":"Fill in the squares that match each row and column's number clues to reveal the hidden picture before time runs out.","full":["Each row and column number tells you how many filled squares run together, in order, along that line.","Click or drag to fill squares, switch to Mark to cross out squares you know are empty, or use arrows plus Space or X.","Complete the picture correctly before the clock runs out; marking squares you're sure about helps you avoid mistakes.","When a line's numbers add up close to its length, work out the overlapping squares first since those must always be filled."]},"tubeSort":{"blurb":"Pour coloured liquid between tubes until every tube contains just one colour, or a single empty tube.","full":["Sort the mixed-up colour layers so each tube ends up holding only one colour, or stays empty.","Click a tube to select it, then click the tube you want to pour into; keys 1-9 select tubes the same way.","You can only pour a colour onto a matching colour or into an empty tube, and only the top unbroken layer of colour moves at once.","Use Z to undo a bad pour, but R restarts the whole puzzle and costs a life, so plan ahead before pouring."]},"blockFit":{"blurb":"Place all three shapes onto the grid to fill and clear rows or columns before the board runs out of room.","full":["Drop each of the three offered shapes onto the board; filling an entire row or column clears it and scores points.","Drag a shape onto the board, or press 1-3 to pick a shape, aim with the arrows, and press Space to drop it.","Once you place all three shapes, a new set appears, and the game ends if none of them can fit anywhere on the board.","Clearing rows and columns in the same move scores extra, so look for placements that complete more than one line at once."]},"floodFill":{"blurb":"Change the top-left square's colour to flood-fill the whole board in one colour before you run out of moves.","full":["Starting from the top-left corner, the goal is to make the entire board a single colour.","Click a colour, or press 1-6, to change your region to that colour; any matching neighbouring squares join your region too.","Each colour change counts as one move, and you must fill the whole board within the move limit to win.","Picking the colour that captures the most new squares each turn, rather than the biggest single blob, usually clears the board faster."]},"oddTileOut":{"blurb":"Spot the one tile shaded slightly differently from the rest and click it before the clock runs out.","full":["Scan the grid of nearly identical tiles to find the single one with a slightly different shade.","Click or tap the odd tile as soon as you spot it.","A correct pick adds time to the clock and moves you to a harder grid; a wrong pick costs you time.","The shade difference gets subtler as you progress, so scan the grid in sections rather than staring at the center."]},"numberGrid":{"blurb":"Slide tiles in one direction so matching numbers merge into their sum and build toward the biggest tile you can.","full":["Every move slides all tiles as far as possible in one direction, and two tiles with the same number merge into one with their sum.","Move with the arrow keys or WASD, or swipe on touch.","A new tile appears after each move, and the game ends when the board is full and no more merges are possible.","Keep your highest tile parked in a corner and build toward it, rather than merging in a direction that scatters your big numbers."]},"discFlip":{"blurb":"Sandwich the rival's discs between two of yours in a straight line to flip them to your colour.","full":["Sandwich a line of the rival's discs between two of yours, horizontally, vertically, or diagonally, to flip them to your colour.","Click one of the dotted squares to place a disc there; arrows plus Space select a square the same way.","You must place a disc where it captures at least one line of opposing discs; whoever has the most discs when the board fills wins.","Corners can never be flipped once taken, so controlling the corners is usually worth more than flipping discs early."]},"draughts":{"blurb":"Move your pieces diagonally, jump to capture the rival's, and crown a king when you reach the far row.","full":["Move your pieces one diagonal step at a time toward the rival's side of the board.","Click a piece and then a highlighted square to move it; if a capturing jump is available, you must take it.","Jump over an adjacent rival piece into an empty square beyond it to capture that piece; multiple jumps in one turn are possible.","Reach the far row with a piece to crown it a king, letting it move and capture diagonally in any direction; beat the rival to move on."]},"seedSow":{"blurb":"Scoop the seeds from one of your pits and sow them counter-clockwise to fill your store with more than the rival.","full":["Empty one of your own pits and drop one seed into each pit going counter-clockwise around the board, including your store.","Click one of your pits in the bottom row, or press 1-6, to sow the seeds inside it.","If your last seed lands in your own store, you get another turn; sowing skips the rival's store as you pass it.","The game ends when one side's pits are empty, and whoever has banked more seeds in their store wins."]},"fiveInRow":{"blurb":"Take turns placing stones and be the first to line up five in a row, horizontally, vertically, or diagonally.","full":["Place stones on intersections, alternating turns with the rival, to be first to form an unbroken line of five.","Click an intersection to place a stone there; arrows plus Space select an intersection the same way.","A line of five can run horizontally, vertically, or diagonally, and once formed the game ends immediately.","Watch for the rival building an open line of three or four, since that can create two winning threats you can't block both of."]},"timelineSort":{"blurb":"Tap historical events in the order they happened, from earliest to latest, using 190+ verified dates.","full":["Practice world history by sequencing real events on a timeline from earliest to most recent.","Tap the events in the order you think they happened; arrow keys plus Space also work.","Each correct pick reveals its year, but four wrong taps ends the run.","Tip: use revealed years as anchors to narrow down where later events must fall."]},"gridPilot":{"blurb":"Fly your plane to given coordinates, then use star positions to find midpoints and distances.","full":["Practice coordinate geometry: reading grid coordinates, midpoints, and distance between points.","Tap or drag on the grid to fly to a coordinate, or use arrow keys plus Space.","In star rounds, tap an answer or press 1-4 to answer midpoint and distance questions.","Tip: count grid squares carefully in both directions before committing to an answer."]},"continentClick":{"blurb":"Tap the continent, ocean or island named on a real map of Earth's coastlines.","full":["Learn world geography using a map drawn from actual coastline data.","Tap the map to answer, or move the cursor with arrow keys and pick with Space.","Three missed taps ends the run, so read each prompt carefully before tapping.","Tip: islands and oceans can be small targets, so picture their real shape before tapping."]},"clockMaster":{"blurb":"Read a realistic analog clock and answer time, elapsed-time and duration questions before it runs out.","full":["Practice reading analog clocks and calculating elapsed time and durations.","Click an answer or press 1-4 to respond to each clock question.","Three missed answers ends the run, so watch the clock hands closely.","Tip: check whether a question asks for the current time or an elapsed duration, since they're worked out differently."]},"numberHunt":{"blurb":"Tap every number in a 48-number grid that fits the given rule before time runs out.","full":["Practice number properties like primes, squares, cubes and digit sums.","Tap the matching numbers in the grid, or use arrow keys plus Space.","Three wrong taps ends the run, so check each number against the rule before tapping.","Tip: rules can combine ideas, like even squares, so re-read the rule after every few taps."]},"bitFlip":{"blurb":"Flip glowing lights to build binary numbers, then read or convert them to and from decimal.","full":["Learn binary numbers and how they convert to and from decimal.","Tap the lights or press 1-8 (left to right) to flip them; in read and convert rounds, press 1-4 to answer.","Three missed answers ends the run.","Tip: each light's value doubles as you move left, just like decimal place value but based on 2."]},"whatNext":{"blurb":"Spot the pattern in a sequence of numbers, letters, shapes, colors or arrows and pick what comes next.","full":["Practice pattern recognition and logical reasoning across numbers, letters, shapes, colors and arrows.","Click an answer or press 1-4 to choose what comes next in the sequence.","Three missed answers ends the run.","Tip: name the pattern in your head (add 3, alternate colors, rotate clockwise) before checking the choices."]},"cipherWheel":{"blurb":"Encode or decode secret words with a real Caesar cipher wheel by matching coded letters to plain ones.","full":["Learn how the Caesar cipher shifts letters to encode and decode secret messages.","Type letters or tap the on-screen keys; Enter checks your answer and Backspace deletes.","On Hard mode, turn the wheel itself with the ◀ and ▶ buttons to line up the shift.","Tip: compare just one matching pair of letters on the inner and outer rings to find the shift amount."]},"capitalMatch":{"blurb":"Match each country to its true capital city in a fast world-trivia quiz.","full":["Learn world capitals and geography through rapid-fire matching.","Click an answer or press 1-4 to pick the correct capital.","Three missed answers ends the run.","Tip: at higher levels, decoy answers are capitals from the same region, so know your neighboring countries well."]},"mathRain":{"blurb":"Type the answer to each falling sum before it hits the floor and pop it.","full":["Practice quick mental addition and subtraction under time pressure.","Type digits and use Backspace to fix mistakes, then press Enter to send your answer; or tap the on-screen number pad.","Three missed answers ends the run.","Tip: solve the sum closest to the floor first, since it will hit bottom soonest."]},"timesGrid":{"blurb":"Tap the grid cell where the row number times the column number equals the target.","full":["Practice multiplication facts using a row-by-column times table grid.","Tap a cell, or press 1 to select and Space to confirm; arrow keys move the selection and Space picks.","Three missed answers ends the run.","Tip: scan one row at a time and multiply by the column number instead of guessing randomly."]},"fractionSlice":{"blurb":"Shade the correct number of pizza slices to match the given fraction.","full":["Practice fractions by matching a shaded portion of a pizza to a written fraction.","Tap slices to shade them in, then press Check; or use arrow keys to move, Space to shade, and Enter to check.","Three missed answers ends the run.","Tip: the denominator tells you how many total slices the pizza is cut into, and the numerator tells you how many to shade."]},"balanceScales":{"blurb":"The scale is balanced. Figure out how much the mystery box x weighs.","full":["Practice basic algebra by solving for an unknown weight on a balanced scale.","Click an answer or press 1-4 to submit your answer.","Three missed answers ends the run.","Tip: cancel out equal, known weights from both sides of the scale first to isolate x."]},"lineDart":{"blurb":"Throw a dart at the spot where the number belongs on the number line; the closer, the more points.","full":["Practice estimating positions of numbers on a number line.","Tap or drag and release to throw the dart, or aim with the Left/Right arrows and throw with Space.","You get eight darts per game, and accuracy determines your score.","Tip: check the labeled endpoints of the line first to judge the scale before throwing."]},"unitSnap":{"blurb":"Convert between everyday units like metres, grams, litres, minutes, feet and pounds before time runs out.","full":["Practice converting between metric and everyday measurement units.","Click an answer or press 1-4 to submit your conversion.","Three missed answers ends the run.","Tip: figure out whether you're converting to a bigger or smaller unit, since that decides whether you multiply or divide."]},"coinChange":{"blurb":"Build the exact price from coins, or make correct change from a bill, as fast and precisely as you can.","full":["Practice counting money and making change.","Tap coins or press 1-6 to add them; press Enter to pay, Backspace to undo, and c to clear.","Three missed answers ends the run.","Tip: start with the largest coin values first to reach the target using fewer coins."]},"elementHunt":{"blurb":"Find the requested chemical element on a real periodic table before the clock runs out.","full":["Learn the periodic table, including real element positions and families, from hydrogen to oganesson.","Tap the right cell, or move with arrow keys and pick with Space.","Three missed answers ends the run.","Tip: use the element's group (column) and period (row) to narrow down its family before searching cell by cell."]},"bodyMap":{"blurb":"Find each of sixteen organs on a real body diagram by name, clue, or function.","full":["Learn human anatomy by locating real organs and understanding what each one does.","Tap the organ, or cycle through options with arrow keys and pick with Space.","Three missed answers ends the run, and a wrong guess reveals the correct answer.","Tip: function clues describe what an organ does, not just where it sits, so think in terms of its job."]},"matterSort":{"blurb":"Sort falling objects into solid, liquid, gas or plasma as they drop from the sky.","full":["Learn the states of matter, including tricky examples like lightning (plasma) and dry ice.","Click a bin or press 1-4 to sort each object; arrow keys work too.","Three missed answers ends the run.","Tip: think about what the object does at room temperature, and watch for surprises like dry ice, which skips the liquid state."]},"foodChain":{"blurb":"Put each food chain in order, from producer up to the top predator, across different habitats.","full":["Learn how energy flows through ecosystems like grassland, ocean, forest and tundra.","Tap the links in order, or use arrow keys plus Space.","Four wrong taps ends the run.","Tip: start with the producer, usually a plant, since energy flows from what's eaten to what eats it."]},"colorLab":{"blurb":"Learn how light mixes to white and ink mixes to black by answering real color-physics questions.","full":["Learn the real physics of additive (light) and subtractive (ink) color mixing used in screens and printers.","Click an answer or press 1-4 to submit your answer.","Three missed answers ends the run.","Tip: light adds up toward white, while ink and pigment subtract down toward black."]},"planetParade":{"blurb":"Line up the eight planets in the correct order, by distance, size, mass or spin speed.","full":["Learn real facts about the solar system's planets, including their distances, sizes, masses and spin speeds.","Tap the tiles in the correct order, or use arrow keys plus Space.","Four wrong taps ends the run.","Tip: check which property, distance, size, mass or spin, a round is testing before you start ordering."]},"unscramble":{"blurb":"Read the clue, then spell the scrambled word from its letter tiles before the timer bar runs out.","full":["Practice spelling and vocabulary by unscrambling letter tiles into a word matching a clue.","Tap tiles or type letters; press Backspace to undo, Space to shuffle, and Enter for a hint (costs 5 points).","The timer bar counts down, so speed matters.","Tip: guess the word from the clue first, then hunt for its letters instead of solving it as a pure puzzle."]},"synonymSwat":{"blurb":"Whack the mole holding a word that means the same as the target, and dodge the rest.","full":["Practice vocabulary and synonyms by matching words with the same meaning.","Tap a mole or press 1-9, matching the number shown on its hole.","A wrong whack or a missed answer costs a life.","Tip: read every mole's word before swatting, since a close-but-wrong meaning can look tempting."]},"rootMatch":{"blurb":"Match Greek and Latin roots and prefixes to their true meanings.","full":["Learn the Greek and Latin roots, prefixes and combining forms that build thousands of English words.","Tap a root, then tap its meaning; arrow keys plus Space also work.","Matching correctly builds your streak and score.","Tip: think of an English word that uses the root, since it often gives away the root's meaning."]},"homophoneHop":{"blurb":"Hop to the homophone that correctly fits the meaning of the sentence.","full":["Practice distinguishing homophones, words that sound alike but mean different things.","Click an answer or press 1-4 to pick the word that fits.","Three missed answers ends the run.","Tip: read the whole sentence for meaning first, not just the sound of the missing word."]},"prefixPop":{"blurb":"Add the correct Greek or Latin prefix so the word matches its clue.","full":["Learn how Greek and Latin prefixes change a word's meaning.","Click an answer or press 1-4 to pick the correct prefix.","Three missed answers ends the run.","Tip: focus on what the clue implies, like 'not' or 'again', since that usually points straight to the prefix."]},"sentenceScramble":{"blurb":"Tap the jumbled words in the right order to rebuild the sentence.","full":["Practice sentence structure and grammar by reordering scrambled words.","Tap the words in order, or use arrow keys plus Space.","Four wrong taps ends the run.","Tip: find the subject and verb first, since they usually anchor the rest of the sentence."]},"missingLetter":{"blurb":"Pick the letters that complete a tricky word before the clock runs out.","full":["Practice spelling tricky words by filling in a missing letter.","Click an answer or press 1-4 to pick the missing letter.","Three missed answers ends the run.","Tip: say the word aloud in your head to hear which letter sound is missing."]},"speechSort":{"blurb":"Sort falling words into their correct bin: noun, verb, adjective or adverb.","full":["Learn parts of speech by classifying words as nouns, verbs, adjectives or adverbs.","Click a bin or press 1-4 to sort each word; arrow keys work too.","Three missed answers ends the run.","Tip: try the word in a sample sentence to hear whether it names a thing, shows action, or describes something."]}};